-- Exam mode (07-exam-mode.md, 03-data-model.md §2.3). Generated by `prisma migrate diff`, with the
-- CHECKs added by hand: Prisma cannot express them (and does not diff them).
--
-- Deviations from 03 §2.3, both logged as decisions: the scope is topic_keys text[] ("src:<source_id>"
-- until topics exist) instead of topic_ids uuid[] (D-53), and target_retention is double precision,
-- not real, because float4 reads 0.9 back as 0.8999999762 (D-54).

-- CreateTable
CREATE TABLE "exams" (
    "id" UUID NOT NULL,
    "user_id" TEXT NOT NULL,
    "exam_date" DATE NOT NULL,
    "topic_keys" TEXT[],
    "target_retention" DOUBLE PRECISION NOT NULL DEFAULT 0.9,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "exams_pkey" PRIMARY KEY ("id"),
    -- Hand edit: an exam covers at least one note. Prisma creates list columns nullable, so the
    -- CHECK also refuses NULL (cardinality(NULL) is NULL, which a CHECK would let through).
    CONSTRAINT "exams_topic_keys_not_empty" CHECK ("topic_keys" IS NOT NULL AND cardinality("topic_keys") > 0),
    -- Hand edit: the API refuses targets outside this range (07 §6).
    CONSTRAINT "exams_target_retention_range" CHECK ("target_retention" BETWEEN 0.8 AND 0.97)
);

-- CreateIndex
CREATE INDEX "exams_user" ON "exams"("user_id", "exam_date");

-- AddForeignKey
ALTER TABLE "exams" ADD CONSTRAINT "exams_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
